insert into public.closed_lost_leads (name, email, phone, project_type, quoted_amount, lost_reason, last_contact_date, ghl_notes) values
('Rachel Nguyen','rnguyen@example.com','+1-602-555-0231','Backyard patio + turf',31500,'Went with competitor - faster quote','2025-04-18','Loved the travertine samples. Husband wanted to move before summer. Competitor quoted in 2 days.'),
('Bill & Donna Kowalski','bkowalski@example.com','+1-480-555-0264','Pool deck remodel',24800,'Price shopper','2025-09-02','Compared 4 bids. Said we were 15% high. Very engaged on the design call though.'),
('Marcus Webb','mwebb@example.com','+1-602-555-0298','Outdoor kitchen',46000,'Went cold','2026-01-22','Was excited, asked for render twice. Then stopped replying after the holidays.'),
('Sofia Alvarez','salvarez@example.com','+1-623-555-0307','Pergola + fire pit',18900,'Timing - travel','2025-11-10','Family trip to Mexico, said circle back in spring. Nobody followed up.'),
('Greg Thompson','gthompson@example.com','+1-480-555-0322','Full backyard remodel',72000,'Budget - postponed','2025-06-30','Loved everything. Got quoted before bonus season, said maybe next year.'),
('Angela Marsh','amarsh@example.com','+1-602-555-0348','Artificial turf + putting green',13400,'Went cold','2026-03-05','Golf fanatic. Wanted putting green for husband''s 50th. Ghosted after quote.'),
('Devon Price','dprice@example.com','+1-623-555-0371','Front yard xeriscape',9800,'Price shopper','2025-08-14','HOA deadline pressure. Went with cheaper bid, complained about them on Nextdoor later per Brittany.'),
('Linda & Hal Osei','losei@example.com','+1-480-555-0390','Ramada + outdoor kitchen',58500,'Went cold','2026-02-11','Retired couple, host grandkids weekly. Asked great questions on site walk. No response to 2 follow-ups.');